style.css:
@-moz-document domain("mail.google.com") {
/* fundo geral */
body {
    background-color: #fff5f7 !important;
}

/* sidebar */
div[role="navigation"] {
    background-color: #ffeef2 !important;
}

/* emails */
tr {
    background-color: rgba(255,255,255,0.7) !important;
}

/* hover */
tr:hover {
    background-color: rgba(255, 182, 193, 0.2) !important;
}

/* textos */
span, td {
    color: #000 !important;
}
}
